#include <iostream>
#include <span>
int main() {
    int buffer[5]{4, 7, 0, 0, 0};
    std::span<const int> values{buffer, 2};
    int sum{};
    for (int value : values) { sum += value; }
    std::cout << values.size() << ' ' << sum << '\n';
}

#include <iostream>
#include <array>
#include <span>
std::size_t findFirst(std::span<const int> values, int target) {
    for (std::size_t i = 0; i < values.size(); ++i) { if (values[i] == target) { return i; } }
    return values.size();
}
int main() {
    std::array<int, 4> values{4, 2, 4, 9};
    std::cout << findFirst(values, 4) << ' ' << findFirst(values, 7) << '\n';
}

