#include <iostream>
#include <vector>
int main() {
    int n{};
    if (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "invalid\n"; return 0; }
    std::vector<int> selected;
    long long sum{};
    for (int i = 0; i < n; ++i) {
        int value{};
        if (!(std::cin >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        if (value >= 0) { selected.push_back(value); sum += value; }
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
    std::cout << selected.size() << ' ' << sum << '\n';
    for (std::size_t i = 0; i < selected.size(); ++i) { if (i != 0) { std::cout << ' '; } std::cout << selected[i]; }
    std::cout << '\n';
}

