#include <iostream>
#include <span>
#include <vector>
long long sum(std::span<const int> values) {
    long long result{};
    for (int value : values) { result += value; }
    return result;
}
int positive(std::span<const int> values) {
    int count{};
    for (int value : values) { if (value > 0) { ++count; } }
    return count;
}
int main() {
    int n{};
    if (!(std::cin >> n) || n < 0 || n > 100) { std::cout << "invalid\n"; return 0; }
    std::vector<int> values;
    for (int i = 0; i < n; ++i) {
        int value{};
        if (!(std::cin >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; }
        values.push_back(value);
    }
    std::cin >> std::ws;
    if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
    std::cout << values.size() << ' ' << sum(values) << ' ' << positive(values) << ' ';
    if (values.empty()) { std::cout << "none\n"; return 0; }
    int minimum = values[0];
    for (int value : values) { if (value < minimum) { minimum = value; } }
    std::cout << minimum << '\n';
}

